SELECT s.wo_number, d.operation_id, d.routing_id, d.name, d.work_center, d.sequence_no, s.status FROM mes_operation_status s JOIN mes_operation_def d ON d.operation_id = s.operation_id WHERE s.wo_number = ? AND s.status = 'ready' AND NOT EXISTS (SELECT 1 FROM mes_operation_edge e LEFT JOIN mes_operation_status ps ON ps.wo_number = s.wo_number AND ps.operation_id = e.predecessor_op WHERE e.routing_id = d.routing_id AND e.successor_op = s.operation_id AND (ps.status IS NULL OR ps.status <> 'complete')) ORDER BY d.sequence_no
